cd /tmp/vally-eval-trial-wF2NEn && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features tests/CheckoutPricing.UnitTest/LoyaltyDiscount && cat > $P/features/pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: the four scenarios below carry values copied verbatim from ac.md (AC-1..AC-4).
  # NOT SETTLED: see "Open decisions" at the end of this file.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket   # AC-1
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket   # AC-2
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket   # AC-3
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer with a tiny basket is charged a whole number of cents   # AC-4
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # OPEN DECISIONS - deliberately NO scenario and NO test exists for these.
  # 1. Platinum tier: no reduction agreed (ac.md "Not decided"). No expected value
  #    exists, so none is encoded. Escalated to DISCUSS.
  # 2. AC-4 title says the reduction lands "in the customer's favour", yet the
  #    expected charge is 7 cents (reduction 0). Rounding the 0.35-cent reduction
  #    up to 1 cent would charge 6. 7 is copied verbatim; business to confirm.
E
cat > tests/CheckoutPricing.UnitTest/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price_for_a_basket()
    {
        // AC-1: Bronze customer is charged the Bronze price for a basket
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
E
ls $P/features tests/CheckoutPricing.UnitTest/LoyaltyDiscount

